-- Independent practice exams; old papers, releases and records remain formal.
-- No historical snapshots or result data are rewritten.

-- @step paper_exam_purpose
-- @replaces-check 042_public_random_paper/paper_pool_scope
-- @check SELECT CASE WHEN (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_paper') = 26 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_paper' AND ((COLUMN_NAME = 'regulation_id' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'business_scope' AND COLUMN_TYPE = 'varchar(16)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'regulation') OR (COLUMN_NAME = 'mode' AND COLUMN_TYPE = 'varchar(16)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'fixed') OR (COLUMN_NAME = 'category_id' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'requires_learning' AND COLUMN_TYPE = 'tinyint unsigned' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = '1') OR (COLUMN_NAME IN ('regulation_ids', 'course_ids', 'rule_config') AND DATA_TYPE = 'json' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL))) = 8 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_paper' AND INDEX_NAME = 'idx_paper_training_pool' AND ((SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'category_id') OR (SEQ_IN_INDEX = 2 AND COLUMN_NAME = 'business_scope') OR (SEQ_IN_INDEX = 3 AND COLUMN_NAME = 'mode') OR (SEQ_IN_INDEX = 4 AND COLUMN_NAME = 'status')) AND NON_UNIQUE = 1 AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) = 4 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='exam_paper' AND COLUMN_NAME='designer_layout' AND DATA_TYPE='json' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='')=1 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='exam_paper' AND ((COLUMN_NAME='required_learning_minutes' AND DATA_TYPE='int' AND COLUMN_TYPE='int unsigned' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='' AND GENERATION_EXPRESSION='' AND COLUMN_COMMENT='') OR (COLUMN_NAME='remark' AND DATA_TYPE='varchar' AND COLUMN_TYPE='varchar(1000)' AND CHARACTER_SET_NAME='utf8mb4' AND COLLATION_NAME='utf8mb4_0900_ai_ci' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='' AND GENERATION_EXPRESSION='' AND COLUMN_COMMENT='')))=2 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='exam_paper' AND COLUMN_NAME='course_ids' AND COLUMN_COMMENT='考前学习课程关联，不参与抽题过滤')=1 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='exam_paper' AND COLUMN_NAME='sort_order' AND DATA_TYPE='int' AND COLUMN_TYPE='int' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT='0' AND EXTRA='' AND GENERATION_EXPRESSION='' AND COLUMN_COMMENT='')=1 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='exam_paper' AND COLUMN_NAME='updated_by' AND DATA_TYPE='bigint' AND COLUMN_TYPE='bigint unsigned' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='' AND GENERATION_EXPRESSION='' AND COLUMN_COMMENT='')=1 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='exam_paper' AND COLUMN_NAME='pool_scope' AND COLUMN_TYPE='varchar(16)' AND CHARACTER_SET_NAME='utf8mb4' AND COLLATION_NAME='utf8mb4_0900_ai_ci' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT='category' AND EXTRA='' AND GENERATION_EXPRESSION='' AND COLUMN_COMMENT='')=1 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='exam_paper' AND COLUMN_NAME='exam_purpose' AND COLUMN_TYPE='varchar(16)' AND CHARACTER_SET_NAME='utf8mb4' AND COLLATION_NAME='utf8mb4_0900_ai_ci' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT='formal' AND EXTRA='' AND GENERATION_EXPRESSION='' AND COLUMN_COMMENT='')=1 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='exam_paper' AND COLUMN_NAME='max_attempts' AND COLUMN_TYPE='int' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT='3' AND EXTRA='' AND GENERATION_EXPRESSION='' AND COLUMN_COMMENT='最大作答次数，模拟考为 NULL')=1 THEN 1 ELSE 0 END AS complete;
ALTER TABLE exam_paper ADD COLUMN exam_purpose VARCHAR(16) NOT NULL DEFAULT 'formal' AFTER business_scope, MODIFY COLUMN max_attempts INT NULL DEFAULT 3 COMMENT '最大作答次数，模拟考为 NULL';

-- @step release_exam_purpose
-- @replaces-check 042_public_random_paper/release_pool_scope
-- @check SELECT CASE WHEN EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'paper_release' AND TABLE_TYPE = 'BASE TABLE' AND ENGINE = 'InnoDB' AND TABLE_COLLATION = 'utf8mb4_0900_ai_ci') AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'paper_release') = 15 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'paper_release' AND ((COLUMN_NAME = 'id' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'NO' AND EXTRA = 'auto_increment') OR (COLUMN_NAME IN ('paper_id', 'created_by') AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME = 'version_no' AND COLUMN_TYPE = 'int unsigned' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME IN ('business_scope', 'mode') AND COLUMN_TYPE = 'varchar(16)' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME = 'category_id' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'requires_learning' AND COLUMN_TYPE = 'tinyint unsigned' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = '0') OR (COLUMN_NAME = 'rule_snapshot' AND DATA_TYPE = 'json' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME IN ('regulation_ids', 'course_ids') AND DATA_TYPE = 'json' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'released_at' AND COLUMN_TYPE = 'datetime(3)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'CURRENT_TIMESTAMP(3)' AND EXTRA = 'DEFAULT_GENERATED'))) = 12 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'paper_release') = 4 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'paper_release' AND ((INDEX_NAME = 'PRIMARY' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'id') OR (INDEX_NAME = 'uk_paper_release_version' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'paper_id') OR (INDEX_NAME = 'uk_paper_release_version' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 2 AND COLUMN_NAME = 'version_no') OR (INDEX_NAME = 'idx_paper_release_category' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'category_id')) AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) = 4 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='paper_release' AND COLUMN_NAME='required_learning_minutes' AND DATA_TYPE='int' AND COLUMN_TYPE='int unsigned' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='' AND GENERATION_EXPRESSION='' AND COLUMN_COMMENT='')=1 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='paper_release' AND COLUMN_NAME='pool_scope' AND COLUMN_TYPE='varchar(16)' AND CHARACTER_SET_NAME='utf8mb4' AND COLLATION_NAME='utf8mb4_0900_ai_ci' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT='category' AND EXTRA='' AND GENERATION_EXPRESSION='' AND COLUMN_COMMENT='')=1 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='paper_release' AND COLUMN_NAME='exam_purpose' AND COLUMN_TYPE='varchar(16)' AND CHARACTER_SET_NAME='utf8mb4' AND COLLATION_NAME='utf8mb4_0900_ai_ci' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT='formal' AND EXTRA='' AND GENERATION_EXPRESSION='' AND COLUMN_COMMENT='')=1 THEN 1 ELSE 0 END AS complete;
ALTER TABLE paper_release ADD COLUMN exam_purpose VARCHAR(16) NOT NULL DEFAULT 'formal' AFTER business_scope;

-- @step record_exam_purpose
-- @replaces-check 015_demo_slimming/objective_record_columns
-- @check SELECT CASE WHEN (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record' AND ((COLUMN_NAME = 'id' AND DATA_TYPE = 'bigint' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT IS NULL AND EXTRA = 'auto_increment') OR (COLUMN_NAME IN ('paper_id', 'user_id') AND DATA_TYPE = 'bigint' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT IS NULL AND EXTRA = '') OR (COLUMN_NAME IN ('regulation_id', 'assignment_id', 'active_assignment_id', 'release_id', 'category_id') AND DATA_TYPE = 'bigint' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL AND EXTRA = '') OR (COLUMN_NAME IN ('source', 'difficulty') AND DATA_TYPE = 'varchar' AND COLUMN_TYPE = 'varchar(16)' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL AND EXTRA = '') OR (COLUMN_NAME = 'rule_snapshot' AND DATA_TYPE = 'json' AND COLUMN_TYPE = 'json' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL AND EXTRA = '') OR (COLUMN_NAME = 'snapshot_origin' AND DATA_TYPE = 'varchar' AND COLUMN_TYPE = 'varchar(32)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'legacy_unavailable' AND EXTRA = '') OR (COLUMN_NAME = 'attempt_no' AND DATA_TYPE = 'int' AND COLUMN_TYPE = 'int' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = '1' AND EXTRA = '') OR (COLUMN_NAME = 'status' AND DATA_TYPE = 'varchar' AND COLUMN_TYPE = 'varchar(16)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'in_progress' AND EXTRA = '') OR (COLUMN_NAME = 'score' AND DATA_TYPE = 'decimal' AND COLUMN_TYPE = 'decimal(5,2)' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL AND EXTRA = '') OR (COLUMN_NAME IN ('started_at', 'deadline_at') AND DATA_TYPE = 'datetime' AND COLUMN_TYPE = 'datetime(3)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT IS NULL AND EXTRA = '') OR (COLUMN_NAME IN ('submitted_at', 'draft_saved_at', 'graded_at') AND DATA_TYPE = 'datetime' AND COLUMN_TYPE = 'datetime(3)' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL AND EXTRA = '') OR (COLUMN_NAME = 'draft_revision' AND DATA_TYPE = 'int' AND COLUMN_TYPE = 'int unsigned' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = '0' AND EXTRA = '') OR (COLUMN_NAME = 'draft_payload_hash' AND DATA_TYPE = 'char' AND COLUMN_TYPE = 'char(64)' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL AND EXTRA = '') OR (COLUMN_NAME = 'submission_method' AND DATA_TYPE = 'varchar' AND COLUMN_TYPE = 'varchar(16)' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL AND EXTRA = '') OR (COLUMN_NAME = 'grading_state' AND DATA_TYPE = 'varchar' AND COLUMN_TYPE = 'varchar(32)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'not_submitted' AND EXTRA = '') OR (COLUMN_NAME = 'created_at' AND DATA_TYPE = 'datetime' AND COLUMN_TYPE = 'datetime(3)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'CURRENT_TIMESTAMP(3)' AND EXTRA = 'DEFAULT_GENERATED') OR (COLUMN_NAME = 'updated_at' AND DATA_TYPE = 'datetime' AND COLUMN_TYPE = 'datetime(3)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'CURRENT_TIMESTAMP(3)' AND EXTRA = 'DEFAULT_GENERATED on update CURRENT_TIMESTAMP(3)'))) = 26 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record' AND INDEX_NAME = 'PRIMARY') = 1 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record' AND INDEX_NAME = 'PRIMARY' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) = 1 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record' AND INDEX_NAME = 'uk_paper_user_attempt') = 3 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record' AND INDEX_NAME = 'uk_paper_user_attempt' AND NON_UNIQUE = 0 AND ((SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'paper_id') OR (SEQ_IN_INDEX = 2 AND COLUMN_NAME = 'user_id') OR (SEQ_IN_INDEX = 3 AND COLUMN_NAME = 'attempt_no')) AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) = 3 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record' AND INDEX_NAME = 'uk_assignment_attempt') = 2 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record' AND INDEX_NAME = 'uk_assignment_attempt' AND NON_UNIQUE = 0 AND ((SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'assignment_id') OR (SEQ_IN_INDEX = 2 AND COLUMN_NAME = 'attempt_no')) AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) = 2 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record' AND INDEX_NAME = 'uk_active_assignment') = 1 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record' AND INDEX_NAME = 'uk_active_assignment' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'active_assignment_id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) = 1 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record' AND INDEX_NAME = 'idx_user_paper_status') = 3 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record' AND INDEX_NAME = 'idx_user_paper_status' AND NON_UNIQUE = 1 AND ((SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'user_id') OR (SEQ_IN_INDEX = 2 AND COLUMN_NAME = 'paper_id') OR (SEQ_IN_INDEX = 3 AND COLUMN_NAME = 'status')) AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) = 3 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record' AND INDEX_NAME = 'idx_regulation_status') = 2 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record' AND INDEX_NAME = 'idx_regulation_status' AND NON_UNIQUE = 1 AND ((SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'regulation_id') OR (SEQ_IN_INDEX = 2 AND COLUMN_NAME = 'status')) AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) = 2 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record' AND INDEX_NAME = 'idx_paper_status') = 2 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record' AND INDEX_NAME = 'idx_paper_status' AND NON_UNIQUE = 1 AND ((SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'paper_id') OR (SEQ_IN_INDEX = 2 AND COLUMN_NAME = 'status')) AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) = 2 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record' AND INDEX_NAME = 'idx_status_deadline') = 2 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record' AND INDEX_NAME = 'idx_status_deadline' AND NON_UNIQUE = 1 AND ((SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'status') OR (SEQ_IN_INDEX = 2 AND COLUMN_NAME = 'deadline_at')) AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) = 2 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record' AND INDEX_NAME = 'idx_exam_record_release') = 1 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record' AND INDEX_NAME = 'idx_exam_record_release' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'release_id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) = 1 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_record' AND COLUMN_NAME IN ('last_heartbeat_at','device_summary','grading_revision','switch_count')) = 0 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='exam_record' AND COLUMN_NAME='exam_purpose' AND COLUMN_TYPE='varchar(16)' AND CHARACTER_SET_NAME='utf8mb4' AND COLLATION_NAME='utf8mb4_0900_ai_ci' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT='formal' AND EXTRA='' AND GENERATION_EXPRESSION='' AND COLUMN_COMMENT='')=1 THEN 1 ELSE 0 END AS complete;
ALTER TABLE exam_record ADD COLUMN exam_purpose VARCHAR(16) NOT NULL DEFAULT 'formal' AFTER paper_id;
